mapper.select:
SELECT (SELECT count(1) FROM b_user bu, (SELECT bur.user_id FROM b_user bur, r_user_tenant rut WHERE bur.flag = 1 AND rut.flag = 1 AND bur.user_id = rut.user_id AND rut.tenant_id = #{tenantId}
AND rut.organization_id = #{orgId}
) tmp WHERE bu.flag = 1 AND bu.recommend_user_id = tmp.user_id AND bu.create_time BETWEEN #{startTime} AND #{endTime}) AS recommendCount, (SELECT COUNT(1) FROM b_user bu, r_user_tenant rut WHERE bu.flag = 1 AND rut.flag = 1 AND bu.user_id = rut.user_id AND bu.tenant_id = #{tenantId}
AND rut.organization_id = #{orgId}
AND rut.create_time BETWEEN #{startTime} AND #{endTime}) AS newCount, (SELECT COUNT(1) FROM b_user bu, r_user_tenant rut WHERE bu.flag = 1 AND rut.flag = 1 AND bu.user_id = rut.user_id AND bu.tenant_id = #{tenantId}
AND rut.organization_id = #{orgId}
) AS totalCount

SELECT (SELECT COUNT(wf.form_id)
        FROM wf_form wf
        WHERE wf.flag = 1
          AND wf.form_type_id = 1
          AND wf.tenant_id = #{tenantId}

            AND wf.current_org_id = #{orgId}

          AND wf.create_time BETWEEN #{startTime} AND #{endTime}) AS newCount,
       (SELECT COUNT(wf.form_id)
        FROM wf_form wf
        WHERE wf.flag = 1
          AND wf.form_type_id = 1
          AND wf.tenant_id = #{tenantId}

            AND wf.current_org_id = #{orgId}

        ) AS totalCount

SELECT IFNULL(t1.totalCount, 0) AS totalCount, IFNULL(t1.totalAmount, 0) AS totalAmount, IFNULL(t2.newCount, 0) AS newCount, IFNULL(t2.newAmount, 0) AS newAmount FROM ( SELECT COUNT(sc.service_contract_id) AS totalCount, SUM(sc.amount) AS totalAmount FROM wf_form wf, sc_service_contract sc WHERE wf.flag = 1 AND sc.flag = 1 AND wf.form_id = sc.form_id AND wf.form_type_id = 1 AND wf.tenant_id = #{tenantId}
AND wf.current_org_id = #{orgId}
) t1, ( SELECT COUNT(sc.service_contract_id) AS newCount, SUM(sc.amount) AS newAmount FROM wf_form wf, sc_service_contract sc WHERE wf.flag = 1 AND sc.flag = 1 AND wf.form_id = sc.form_id AND wf.form_type_id = 1 AND wf.tenant_id = #{tenantId}
AND wf.current_org_id = #{orgId}
AND sc.signing_time BETWEEN #{startTime} AND #{endTime} ) t2

SELECT (SELECT COUNT(wc.complain_id)
        FROM w_complain wc,
             wf_form wf,
             r_form_consult_complain rfcc
        WHERE wc.flag = 1
          AND wf.flag = 1
          AND wc.complain_id = rfcc.complain_id
          AND wf.form_id = rfcc.consult_id
          AND wc.typef = 1
          AND wc.tenant_id = #{tenantId}

            AND wc.organization_id = #{orgId}

          AND wc.create_time BETWEEN #{startTime} AND #{endTime}
       ) AS newOrderCount,
       (SELECT COUNT(wc.complain_id)
        FROM w_complain wc,
             sc_service_contract ssc,
             r_form_consult_complain rfcc
        WHERE wc.flag = 1
          AND ssc.flag = 1
          AND wc.complain_id = rfcc.complain_id
          AND ssc.service_contract_id = rfcc.consult_id
          AND wc.typef = 2
          AND wc.tenant_id = #{tenantId}

            AND wc.organization_id = #{orgId}

          AND wc.create_time BETWEEN #{startTime} AND #{endTime}
        )    newContractCount
